
package com.camtv.tv; import android.app.Activity; import android.content.SharedPreferences; import android.os.Bundle; import android.view.View; import android.widget.*; import android.net.Uri; public class MainActivity extends Activity { VideoView[] cams = new VideoView[8]; CheckBox[] boxes = new CheckBox[8]; EditText ip, user, pass; public void onCreate(Bundle b) { super.onCreate(b); setContentView(R.layout.activity_main); ip = findViewById(R.id.et_ip); user = findViewById(R.id.et_user); pass = findViewById(R.id.et_pass); SharedPreferences p = getSharedPreferences("CamTV", 0); ip.setText(p.getString("ip", "")); user.setText(p.getString("user", "admin")); pass.setText(p.getString("pass", "")); int[] ids = {R.id.cam1, R.id.cam2, R.id.cam3, R.id.cam4, R.id.cam5, R.id.cam6, R.id.cam7, R.id.cam8}; int[] bIds = {R.id.cb1, R.id.cb2, R.id.cb3, R.id.cb4, R.id.cb5, R.id.cb6, R.id.cb7, R.id.cb8}; for (int i = 0; i < 8; i++) { cams[i] = findViewById(ids[i]); boxes[i] = findViewById(bIds[i]); } findViewById(R.id.btn_save).setOnClickListener(new View.OnClickListener() { public void onClick(View v) { saveAndPlay(); } }); findViewById(R.id.btn_stop).setOnClickListener(new View.OnClickListener() { public void onClick(View v) { for (VideoView vv : cams) vv.stopPlayback(); } }); findViewById(R.id.btn_bg).setOnClickListener(new View.OnClickListener() { public void onClick(View v) { moveTaskToBack(true); } }); findViewById(R.id.btn_test).setOnClickListener(new View.OnClickListener() { public void onClick(View v) { Toast.makeText(MainActivity.this, "تجربة تنبيه", Toast.LENGTH_SHORT).show(); } }); if (!ip.getText().toString().isEmpty()) saveAndPlay(); } void saveAndPlay() { String ipS = ip.getText().toString().trim(); String u = user.getText().toString().trim(); String pw = pass.getText().toString().trim(); SharedPreferences.Editor e = getSharedPreferences("CamTV", 0).edit(); e.putString("ip", ipS); e.putString("user", u); e.putString("pass", pw); e.apply(); for (int i = 0; i < 8; i++) { String url = "rtsp://" + u + ":" + pw + "@" + ipS + ":554/avstream/channel=" + (i + 1) + "/stream=0.sdp"; cams[i].setVideoURI(Uri.parse(url)); cams[i].start(); } } }